#include <regex>
#include <string>
#include <iostream>

int main() {
    std::regex r("([[:alnum:]]+)\\.(cpp|cxx|cc)$", std::regex::icase);
    std::string filename1 = "example.CPP";
    std::string filename2 = "test.cxx";
    std::string filename3 = "script.cc";
    std::string filename4 = "document.txt";

    std::cout << std::boolalpha;
    std::cout << "Filename: " << filename1 << " matches: " << std::regex_match(filename1, r) << std::endl;
    std::cout << "Filename: " << filename2 << " matches: " << std::regex_match(filename2, r) << std::endl;
    std::cout << "Filename: " << filename3 << " matches: " << std::regex_match(filename3, r) << std::endl;
    std::cout << "Filename: " << filename4 << " matches: " << std::regex_match(filename4, r) << std::endl;
    return 0;
}
